look.customCSS:
/* ───── 票签 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(ellipse at 20% 10%,rgba(255,255,255,.5),transparent 60%),#ECE4F7 !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：一条撕下来的票头——底边一排小半圆缺口 */
[data-wk="chathead"]{background:radial-gradient(circle at 8px 100%,#ECE4F7 5px,transparent 5.5px) 0 0/16px 100% repeat-x,#FBF8FF !important;border-bottom:none !important;box-shadow:none !important;padding-bottom:12px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#4B3B66 !important}
[data-wk="headdim"]{color:#A79CC0 !important;letter-spacing:.1em !important}
[data-wk="chatback"] svg{stroke:#4B3B66 !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{border-radius:50% !important;box-shadow:0 0 0 1.4px #9A86C4 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgMTEgTDEyIDQgTDIwIDExIFYyMCBINFonIGZpbGw9J25vbmUnIHN0cm9rZT0nIzRCM0I2Nicgc3Ryb2tlLXdpZHRoPScxLjUnIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/21px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyM0QjNCNjYnLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjUnIGZpbGw9JyM0QjNCNjYnLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjUnIGZpbGw9JyM0QjNCNjYnLz48L3N2Zz4=") center/21px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}

/* 头像：圆的，细边 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 1.4px #9A86C4 !important}

/* 我的话：一张票根。右边一道竖线隔出存根，上下两个半圆缺口 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;color:#4B3B66 !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:radial-gradient(circle at calc(100% - 30px) 0,#ECE4F7 6px,transparent 6.5px),radial-gradient(circle at calc(100% - 30px) 100%,#ECE4F7 6px,transparent 6.5px),linear-gradient(90deg,transparent calc(100% - 30.7px),#9A86C4 calc(100% - 30.7px),#9A86C4 calc(100% - 29.3px),transparent calc(100% - 29.3px)),#FFC7E0 !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important;padding:11px 46px 11px 16px !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"No." !important;position:absolute !important;right:6px !important;top:50% !important;left:auto !important;bottom:auto !important;width:18px !important;height:auto !important;margin-top:-7px !important;background:none !important;border:none !important;transform:none !important;font:600 9px/14px ui-monospace,Menlo,monospace !important;color:#8B6CC9 !important;text-align:center !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::before{content:none !important}
/* 他的话：一块尖头挂牌，左边尖角＋小孔，一根细线连到头像 */
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FBF8FF !important;border:1.4px solid #9A86C4 !important;border-left:none !important;border-radius:0 8px 8px 0 !important;margin-left:20px !important;padding:11px 16px 11px 14px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:-19px !important;top:-1.4px !important;bottom:-1.4px !important;width:20px !important;height:auto !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;transform:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::after{content:"" !important;position:absolute !important;left:-8px !important;top:50% !important;bottom:auto !important;width:7px !important;height:7px !important;margin-top:-3.5px !important;border-radius:50% !important;background:#ECE4F7 !important;border:1.2px solid #9A86C4 !important;transform:none !important}
[data-wk="msg"][data-me="0"][data-first="1"] [data-wk="row"]{position:relative !important}
[data-wk="msg"][data-me="0"][data-first="1"] [data-wk="row"]::before{content:"" !important;position:absolute !important;left:40px !important;top:22px !important;width:30px !important;height:14px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAxNCc+PHBhdGggZD0nTTAgNCBDMTAgMiAxNCAxNCAzMCA5JyBmaWxsPSdub25lJyBzdHJva2U9JyM4QjZDQzknIHN0cm9rZS13aWR0aD0nMS4yJy8+PC9zdmc+") center/contain no-repeat !important;pointer-events:none !important;z-index:0 !important}

/* 时间：豆沙色小字，等宽 */
[data-wk="time"] > span{background:transparent !important;border:none !important;color:#A79CC0 !important;font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;font-size:10.5px !important}
/* 已读：一枚圆红印章；已送达只写一行小字 */
[data-wk="meta"]{color:#A79CC0 !important;font-size:10.5px !important;font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.1em !important}
[data-wk="meta"][data-read="1"]{font-size:0 !important;width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-top:-14px !important;position:relative !important;z-index:2 !important;transform:rotate(-8deg) !important}
[data-wk="meta"][data-read="1"] *{opacity:0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#FBF8FF !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#8B6CC9 !important}
/* 动描：一行斜体小字，前面一道豆沙短线（跟气泡分开） */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{background:transparent !important;border:none !important;box-shadow:none !important;color:#4B3B66 !important;opacity:.75 !important;font-style:italic !important;font-size:13px !important;padding-left:14px !important;border-left:2px solid #8B6CC9 !important;border-radius:0 !important}
/* 系统提示：不带框的一行等宽小字 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#A79CC0 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.08em !important}

/* 底栏：一条票头，顶边一排半圆缺口；左发送右回复，回复是豆沙色票块「发送 ♡」那种 */
[data-wk="composer"]{background:radial-gradient(circle at 8px 0,#ECE4F7 5px,transparent 5.5px) 0 0/16px 100% repeat-x,#FBF8FF !important;border-top:none !important;align-items:center !important;gap:8px !important;padding-top:12px !important}
[data-wk="chatinput"]{background:#fff !important;border:1.4px solid #9A86C4 !important;border-radius:6px !important;color:#4B3B66 !important}
[data-wk="chatinput"]::placeholder{color:#A79CC0 !important}
[data-wk="chatplus"],[data-wk="send"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTEyIDYgVjE4IE02IDEyIEgxOCcgc3Ryb2tlPScjNEIzQjY2JyBzdHJva2Utd2lkdGg9JzEuNicgc3Ryb2tlLWxpbmVjYXA9J3JvdW5kJy8+PC9zdmc+") center/22px no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{position:relative !important;width:62px !important;min-width:62px !important;height:34px !important;border:none !important;border-radius:4px !important;background:#8B6CC9 !important;box-shadow:0 3px 0 #6A4FA6 !important}
[data-wk="chatreply"]::before{content:"回复" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;color:#fff !important;font-size:13px !important;letter-spacing:.2em !important;padding-right:12px !important}
[data-wk="chatreply"]::after{content:"" !important;position:absolute !important;right:8px !important;top:50% !important;width:12px !important;height:11px !important;margin-top:-5.5px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="meta"][data-read="1"]{margin-left:auto !important;margin-right:0 !important;align-self:flex-end !important}

/* 回复键：不写字，紫色小票块，中间一个白色带心的对话框；左右两侧各一个半圆缺口 */
[data-wk="chatreply"]{width:46px !important;min-width:46px !important;height:34px !important;background:radial-gradient(circle at 0 50%,#FBF8FF 4.5px,transparent 5px),radial-gradient(circle at 100% 50%,#FBF8FF 4.5px,transparent 5px),url("data:image/svg+xml;base64,") center/22px no-repeat,#8B6CC9 !important}
[data-wk="chatreply"]::before,[data-wk="chatreply"]::after{content:none !important}

/* ───── 票签 · 第二批：卡片 ───── */
/* 卡片统一：浅紫白底、紫细边、底下一道淡影 */
[data-wk="photocard"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#FBF8FF !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important;color:#4B3B66 !important}
[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#4B3B66 !important;border-color:rgba(154,134,196,.4) !important}
/* 转账＝一张车票：左边粉色主票、右边一截紫色存根，中间一排半圆缺口隔开；收下盖玫粉圆章，退回盖一枚斜的「作废」 */
[data-wk="transfercard"]{position:relative !important;overflow:visible !important;background:radial-gradient(circle at calc(100% - 64px) 0,#ECE4F7 7px,transparent 7.5px),radial-gradient(circle at calc(100% - 64px) 100%,#ECE4F7 7px,transparent 7.5px),linear-gradient(90deg,transparent calc(100% - 64.7px),#9A86C4 calc(100% - 64.7px),#9A86C4 calc(100% - 63.3px),transparent calc(100% - 63.3px)),linear-gradient(90deg,#FFC7E0 calc(100% - 64px),#FFE4F0 calc(100% - 64px)) !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important;padding-top:26px !important}
[data-wk="transfercard"]::before{content:"ADMIT ONE · 转账" !important;position:absolute !important;left:16px !important;top:9px !important;font:600 9px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.2em !important;color:#6A4FA6 !important}
[data-wk="transfercard"] *{color:#4B3B66 !important;border-color:rgba(106,79,166,.25) !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#6A4FA6 !important;font-weight:700 !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:rgba(106,79,166,.35) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:transparent !important}
[data-wk="transferbtn"]{border-radius:4px !important}
[data-wk="transferbtn"][data-part="take"]{background:#8B6CC9 !important;color:#fff !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:#FBF8FF !important;color:#4B3B66 !important;border:1.4px solid #9A86C4 !important}
[data-wk="transferseal"]{border:1.4px solid #8B6CC9 !important;background:transparent !important;color:#6A4FA6 !important;box-shadow:none !important}
[data-wk="transferseal"] *{color:#6A4FA6 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{width:54px !important;height:54px !important;border:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(-12deg) !important}
[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"]{width:54px !important;height:54px !important;border:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(10deg) !important;filter:grayscale(1) !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"] *,[data-wk="transfercard"][data-status="returned"] [data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.7 !important}
/* 红包＝一张入场券：紫色主票＋粉色存根，存根上一颗心 */
[data-wk="rpcard"]{background:radial-gradient(circle at 60px 0,#ECE4F7 7px,transparent 7.5px),radial-gradient(circle at 60px 100%,#ECE4F7 7px,transparent 7.5px),linear-gradient(90deg,transparent 59.3px,rgba(255,255,255,.7) 59.3px,rgba(255,255,255,.7) 60.7px,transparent 60.7px),linear-gradient(90deg,#A48ADA 60px,#8B6CC9 60px) !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important;padding-left:72px !important}
[data-wk="rpcard"] > div:not([data-wk]){padding-left:12px !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"]{display:none !important}
[data-wk="rpcorner"]{display:none !important}
[data-wk="rpseal"]{border:none !important;left:18px !important;top:50% !important;margin-top:-12px !important;width:24px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpseal"] *{display:none !important}
[data-wk="rpcard"][data-status="done"]{filter:saturate(.4) !important;opacity:.8 !important}
[data-wk="rpenvelope"]{background:#8B6CC9 !important;border:1.4px solid #9A86C4 !important;border-radius:18px !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:#6A4FA6 !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpenvelope"][data-stage="open"]{background:#FBF8FF !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#4B3B66 !important}
[data-wk="rpopenbtn"]{background:#FFC7E0 url("data:image/svg+xml;base64,") center/50% no-repeat !important;border:1.4px solid #9A86C4 !important;box-shadow:none !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpamount"]{color:#6A4FA6 !important}
/* 照片：像一张贴在票夹里的照片，四角一点紫色胶带 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:4px !important;background:#ECE4F7 !important}
[data-wk="photoface"] *,[data-wk="phototext"],[data-wk="photocap"],[data-wk="photohint"]{color:#4B3B66 !important}
/* 语音：一张小票，我粉他白 */
[data-wk="voice"][data-me]{background:#FBF8FF !important;border:1.4px solid #9A86C4 !important;border-radius:8px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important}
[data-wk="voice"][data-me="1"]{background:#FFC7E0 !important}
[data-wk="voice"] > *{background:transparent !important;border:none !important;box-shadow:none !important;color:#4B3B66 !important}
[data-wk="voicewave"] span{background:#8B6CC9 !important}
[data-wk="wxcardsky"]{background:#ECE4F7 !important}
[data-wk="wxcardsky"] *{color:#4B3B66 !important}
[data-wk="wxcardsky"] svg{stroke:#8B6CC9 !important}
[data-wk="wxcardsay"]{background:#FBF8FF !important;color:#4B3B66 !important;border-top:1.4px solid #9A86C4 !important}
[data-wk="geopin"]{background:#F0478E !important;box-shadow:0 0 0 3px #fff !important}
[data-wk="geopinstem"]{background:#8B6CC9 !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 1.4px #9A86C4 !important}
/* 拍一拍、通话结束：小票胶囊 */
[data-wk="note"][data-part="pat"],[data-wk="note"][data-part="call"]{display:inline-block !important;background:radial-gradient(circle at 0 50%,#ECE4F7 4px,transparent 4.5px),radial-gradient(circle at 100% 50%,#ECE4F7 4px,transparent 4.5px),#FFC7E0 !important;border:none !important;border-radius:3px !important;color:#4B3B66 !important;padding:2px 16px !important;font-size:12px !important}
[data-wk="note"][data-part="call"] svg{stroke:#4B3B66 !important}
[data-wk="note"][data-part="callsum"]{color:#A79CC0 !important}
/* 线下小结：一张票根，标题像票面上的印字 */
[data-part="offlog"]{background:radial-gradient(circle at 0 50%,#ECE4F7 8px,transparent 8.5px),radial-gradient(circle at 100% 50%,#ECE4F7 8px,transparent 8.5px),#FBF8FF !important;padding:16px 22px !important}
[data-wk="offlogtitle"]{color:#6A4FA6 !important;font-family:ui-monospace,Menlo,monospace !important;letter-spacing:.3em !important}
[data-wk="offlogopen"],[data-wk="offlogredo"],[data-wk="offlogundo"],[data-wk="offlogrestore"]{color:#8B6CC9 !important}
[data-wk="offlogtranscript"]{border-top:1.4px solid #9A86C4 !important}
/* 加号面板：一排排小票 */
[data-wk="chatpanel"]{background:#FBF8FF !important;border-top:1.4px solid #9A86C4 !important}
[data-wk="chattoolicon"]{background:radial-gradient(circle at 0 50%,#FBF8FF 4px,transparent 4.5px),radial-gradient(circle at 100% 50%,#FBF8FF 4px,transparent 4.5px),#FFC7E0 !important;border:none !important;border-radius:6px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important}
[data-wk="chattool"]:nth-child(even) [data-wk="chattoolicon"]{background:radial-gradient(circle at 0 50%,#FBF8FF 4px,transparent 4.5px),radial-gradient(circle at 100% 50%,#FBF8FF 4px,transparent 4.5px),#ECE4F7 !important}
[data-wk="chattoolglyph"],[data-wk="chattoolglyph"] svg{stroke:#4B3B66 !important;color:#4B3B66 !important}
[data-wk="chattoollabel"]{color:#4B3B66 !important}
/* 引用三处：一张小纸签，左边一个打孔 */
[data-wk="quotedraft"]{background:#FBF8FF !important;border-top:1.4px solid #9A86C4 !important}
[data-wk="quote"]{background:radial-gradient(circle at 10px 50%,#ECE4F7 3px,transparent 3.5px),#FBF8FF !important;color:#4B3B66 !important;border:1.4px solid #9A86C4 !important;border-radius:4px !important;padding-left:22px !important;opacity:1 !important}
[data-wk="quote"][data-me="1"]{background:radial-gradient(circle at 10px 50%,#ECE4F7 3px,transparent 3.5px),#FFC7E0 !important}
[data-wk="quoteicon"],[data-wk="quoteclear"]{color:#8B6CC9 !important}
[data-wk="bubble"] [data-wk="quotetext"]{display:block !important;border-left:2px solid #8B6CC9 !important;padding-left:8px !important;opacity:.75 !important}


/* 加号、房子、三个点都换成小票按键（线上线下一样） */
[data-wk="sameroom"],[data-wk="chatmore"]{width:36px !important;min-width:36px !important;height:28px !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatplus"]{width:36px !important;min-width:36px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"]{width:36px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="offline"] [data-wk="chathead"] button[title="给 Ta 一个提示"] *{opacity:0 !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"]{width:36px !important;min-width:36px !important;height:28px !important;border:none !important;box-shadow:none !important;font-size:0 !important;color:transparent !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offcomposer"] button[title="给 Ta 看真实照片"] *{opacity:0 !important}
/* 转账存根里的印章：没收时也要看得清——白底紫字的小圆章 */
[data-wk="transfercard"][data-status="pending"] [data-wk="transferseal"]{background:#FBF8FF !important;border:1.4px solid #6A4FA6 !important;box-shadow:none !important}
[data-wk="transfercard"][data-status="pending"] [data-wk="transferseal"] *{color:#6A4FA6 !important}

[data-wk="offcomposer"] button:not([title]):not([data-wk]){background:url("data:image/svg+xml;base64,") center/26px no-repeat !important;border:none !important;box-shadow:none !important;border-radius:0 !important}
