[data-wk="offcomposer"] button[title="让 Ta 演绎"]{width:46px !important;min-width:46px !important;height:34px !important;border:none !important;border-radius:4px !important;background:radial-gradient(circle at 0 50%,#FBF8FF 4.5px,transparent 5px),radial-gradient(circle at 100% 50%,#FBF8FF 4.5px,transparent 5px),url("data:image/svg+xml;base64,") center/22px no-repeat,#8B6CC9 !important;box-shadow:0 3px 0 #6A4FA6 !important;font-size:0 !important}
[data-wk="offcomposer"] button[title="让 Ta 演绎"] *{opacity:0 !important}


/* 房子、三个点：换成挂牌 */
[data-wk="sameroom"],[data-wk="chatmore"]{width:40px !important;min-width:40px !important;height:28px !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
/* 头像框：一枚邮票——齿孔圆边＋紫色细环，头像压在上面 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;isolation:isolate !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{position:relative !important;z-index:1 !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:none !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;inset:-22% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:0 !important;pointer-events:none !important;filter:drop-shadow(0 2px 2px rgba(106,79,166,.25)) !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{box-shadow:none !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]){position:relative !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"])::before{content:"" !important;position:absolute !important;left:-6px !important;top:calc(50% - 26px) !important;width:52px !important;height:52px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:0 !important}
[data-wk="chathead"] button:has(> [data-wk="avatar"]) > [data-wk="avatar"]{position:relative !important;z-index:1 !important}


/* 发送：不用纸飞机，换成跟顶栏同款的挂牌，里面一个箭头（线上线下一样） */
[data-wk="send"]{width:40px !important;min-width:40px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offcomposer"] button:not([title]):not([data-wk]){width:40px !important;min-width:40px !important;height:28px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
/* 引用待发那条：一张小票——左边紫色存根写 RE.，竖线隔开，上下两个半圆缺口 */
[data-wk="quotedraft"]{background:#FBF8FF !important;border-top:none !important}
[data-wk="quote"][data-draft="1"]{position:relative !important;background:radial-gradient(circle at 44px 0,#FBF8FF 5px,transparent 5.5px),radial-gradient(circle at 44px 100%,#FBF8FF 5px,transparent 5.5px),linear-gradient(90deg,#8B6CC9 44px,#FFC7E0 44px) !important;border:1.4px solid #9A86C4 !important;border-radius:6px !important;padding-left:54px !important;box-shadow:0 3px 0 rgba(106,79,166,.18) !important}
[data-wk="quote"][data-draft="1"]::before{content:"RE." !important;position:absolute !important;left:0 !important;top:0 !important;bottom:0 !important;width:44px !important;display:flex !important;align-items:center !important;justify-content:center !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.1em !important;color:#fff !important}
[data-wk="quote"][data-draft="1"] [data-wk="quoteicon"]{display:none !important}
[data-wk="quote"][data-draft="1"] *{color:#4B3B66 !important}
[data-wk="quoteclear"]{color:#6A4FA6 !important}
/* 气泡上方那条引用：一张小挂牌，跟他的气泡同形状 */
[data-wk="quote"]:not([data-draft]){background:radial-gradient(circle at 12px 50%,#ECE4F7 3px,transparent 3.5px),#FBF8FF !important;border:1.4px solid #9A86C4 !important;border-radius:4px 8px 8px 4px !important;clip-path:polygon(8px 0,100% 0,100% 100%,8px 100%,0 50%) !important;padding-left:22px !important}
[data-wk="quote"]:not([data-draft])[data-me="1"]{background:radial-gradient(circle at 12px 50%,#ECE4F7 3px,transparent 3.5px),#FFC7E0 !important}
